import * as fs from 'node:fs';

/** Test assets for the JXL corpus (assets/jxl, generated by scripts/generate-jxl-assets.sh). */
export const ASSETS = new URL('../../../../assets/jxl/', import.meta.url);

/** Parse a binary PNM (P5/P6/P7) into interleaved samples. */
export function readPnm(name: string): {
  width: number;
  height: number;
  channels: number;
  maxval: number;
  samples: number[];
} {
  const buf = fs.readFileSync(new URL(name, ASSETS));
  let pos = 0;
  const token = (): string => {
    while (/\s/.test(String.fromCharCode(buf[pos]!))) pos++;
    let s = '';
    while (!/\s/.test(String.fromCharCode(buf[pos]!))) s += String.fromCharCode(buf[pos++]!);
    return s;
  };
  const magic = token();
  let width: number;
  let height: number;
  let channels: number;
  let maxval: number;
  if (magic === 'P7') {
    const hdr: Record<string, string> = {};
    for (let t = token(); t !== 'ENDHDR'; t = token()) hdr[t] = t === 'TUPLTYPE' ? token() : token();
    width = Number(hdr.WIDTH);
    height = Number(hdr.HEIGHT);
    channels = Number(hdr.DEPTH);
    maxval = Number(hdr.MAXVAL);
  } else {
    width = Number(token());
    height = Number(token());
    maxval = Number(token());
    channels = magic === 'P5' ? 1 : 3;
  }
  pos++;
  const n = width * height * channels;
  const samples: number[] = [];
  for (let i = 0; i < n; i++) samples.push(maxval > 255 ? buf.readUInt16BE(pos + 2 * i) : buf[pos + i]!);
  return { width, height, channels, maxval, samples };
}

/** Parse a PFM (rows stored bottom-to-top) into top-to-bottom interleaved floats. */
export function readPfm(name: string): { width: number; height: number; channels: number; samples: Float32Array } {
  const buf = fs.readFileSync(new URL(name, ASSETS));
  const header = buf.subarray(0, 64).toString('latin1').split(/\s+/);
  const channels = header[0] === 'PF' ? 3 : 1;
  const width = Number(header[1]);
  const height = Number(header[2]);
  const scale = Number(header[3]);
  let pos = 0;
  for (let ws = 0; ws < 4; pos++) if (/\s/.test(String.fromCharCode(buf[pos]!))) ws++;
  const view = new DataView(buf.buffer, buf.byteOffset + pos);
  const samples = new Float32Array(width * height * channels);
  for (let y = 0; y < height; y++) {
    for (let i = 0; i < width * channels; i++) {
      samples[y * width * channels + i] = view.getFloat32(((height - 1 - y) * width * channels + i) * 4, scale < 0);
    }
  }
  return { width, height, channels, samples };
}
